// Функция — это значение, как число или строка
const sayHi = function() { console.log("Привет!"); };
const sayBye = () => console.log("Пока!");

// Вызов через переменную:
sayHi();   // Привет!
sayBye();  // Пока!

// Функция как аргумент (колбэк):
function doTwice(fn) {  // fn — это функция
  fn();                // вызываем её дважды
  fn();
}

doTwice(sayHi);  // Привет! Привет!
doTwice(() => console.log("Бум"));  // Бум Бум

// applyTwice — функция высшего порядка: принимает функцию
function applyTwice(x, fn) {
  return fn(fn(x));  // применяем fn дважды
}

const double = n => n * 2;
const result = applyTwice(3, double);
console.log(result);  // 12

// Как это работает:
// 1. applyTwice(3, double)
// 2. fn(fn(3)) → fn(6) → 12

// Аргумент fn — это НЕ строка и НЕ число, а ФУНКЦИЯ

