const fruits = ["apple", "banana", "cherry"];

// .forEach — перебор каждого элемента
fruits.forEach(fruit => {
  console.log(fruit);  // apple, banana, cherry
});

// С индексом:
fruits.forEach((fruit, index) => {
  console.log(`${index}: ${fruit}`);
  // 0: apple, 1: banana, 2: cherry
});

// .forEach НЕ возвращает результат:
const result = fruits.forEach(f => f.toUpperCase());
console.log(result);  // undefined

const nums = [1, 2, 3, 4];

// .map — преобразует каждый элемент
const doubled = nums.map(n => n * 2);
console.log(doubled);  // [2, 4, 6, 8]

// .map НЕ меняет оригинал:
console.log(nums);     // [1, 2, 3, 4] — цел!

// Превращаем числа в строки:
const strs = [1, 2, 3].map(n => `#${n}`);
console.log(strs);     // ["#1", "#2", "#3"]

const nums = [1, 2, 3, 4, 5, 6];

// .filter — отбор только чётных
const evens = nums.filter(n => n % 2 === 0);
console.log(evens);  // [2, 4, 6]

// .filter НЕ меняет оригинал:
console.log(nums);   // [1, 2, 3, 4, 5, 6] — цел!

// Фильтруем слова по длине:
const words = ["hi", "hello", "hey"];
const long = words.filter(w => w.length > 2);
console.log(long);   // ["hello"]

const words = ["apple", "banana", "avocado", "cherry"];

// Цепочка: сначала фильтр, потом преобразование
const result = words
  .filter(w => w.startsWith("a"))   // ["apple", "avocado"]
  .map(w => w.toUpperCase());        // ["APPLE", "AVOCADO"]

console.log(result);
// Порядок важен: filter → map, а не map → filter
// Сначала отбираем, потом меняем — быстрее

const arr = ["a", "b", "c"];

// Три аргумента: элемент, индекс, массив
arr.forEach((item, index, array) => {
  console.log(`${index}: ${item}`);
  // 0: a, 1: b, 2: c
});

// map с индексом — нумерация:
const numbered = arr.map((item, i) => `${i + 1}. ${item}`);
console.log(numbered);  // ["1. a", "2. b", "3. c"]

// Callback Hell — пирамида смерти:
setTimeout(() => {
  console.log("1");
  setTimeout(() => {
    console.log("2");
    setTimeout(() => {
      console.log("3");
      setTimeout(() => {
        console.log("4");  // куда уже вложить...
      }, 1000);
    }, 1000);
  }, 1000);
}, 1000);

// async/await решает (урок 24):
// await sleep(1000);
// console.log("1");
// await sleep(1000);
