// Функция высшего порядка возвращает новую функцию
function createMultiplier(mult) {
  return function(x) {   // возвращаем функцию
    return x * mult;     // mult запомнен из замыкания
  };
}

const double = createMultiplier(2);
const triple = createMultiplier(3);
console.log(double(5));  // 10
console.log(triple(5));  // 15

// Каждая функция 'помнит' свой mult

